        return true;
    case 0x07C50:   // op 12
        if (__builtin_expect(g_geom_check != 0, 0)) spu_geom_check("op12", 0x07C50, run_07c50, s);
        geomfn_07c50(s);
        return true;
    case 0x07E40:   // op 14
