        geomfn_07e40(s);
        return true;
    case 0x07E70:   // op 15
        if (__builtin_expect(g_geom_check != 0, 0)) spu_geom_check("op15", 0x07E70, run_07e70, s);
        geomfn_07e70(s);
        return true;
    case 0x08C80:   // op 0
        geomfn_08c80(s);
        return true;
    case 0x09FD8:   // op 30
        geomfn_09fd8(s);
        return true;
    case 0x0AFD0:   // op 35
        if (__builtin_expect(g_geom_check != 0, 0)) spu_geom_check("op35", 0x0AFD0, run_0afd0, s);
        geomfn_0afd0(s);
        return true;
    case 0x0B280:   // op 24
        geomfn_0b280(s);
        return true;
    case 0x0B300:   // op 9
